--
-- Name: vw_municipio_indicadores; Type: VIEW; Schema: sinisa; Owner: -
--

CREATE VIEW sinisa.vw_municipio_indicadores AS
 SELECT m.cod_ibge,
    m.nome_municipio,
    m.uf,
    m.regiao,
    m.populacao_total,
    max(r.valor) FILTER (WHERE ((r.codigo_indicador)::text = 'IRS0001'::text)) AS irs0001_cobertura_coleta,
    max(r.valor) FILTER (WHERE ((r.codigo_indicador)::text = 'IRS0005'::text)) AS irs0005_cobertura_coleta_seletiva,
    max(r.valor) FILTER (WHERE ((r.codigo_indicador)::text = 'IRS1004'::text)) AS irs1004_massa_per_capita,
    max(r.valor) FILTER (WHERE ((r.codigo_indicador)::text = 'IRS3001'::text)) AS irs3001_desempenho_coleta_seletiva,
    max(r.valor) FILTER (WHERE ((r.codigo_indicador)::text = 'IRS3002'::text)) AS irs3002_disposicao_inadequada,
    max(r.valor) FILTER (WHERE ((r.codigo_indicador)::text = 'IRS3010'::text)) AS irs3010_recuperacao_reciclaveis
   FROM (sinisa.municipio m
     JOIN sinisa.resultado_indicador r ON ((r.cod_ibge = m.cod_ibge)))
  GROUP BY m.cod_ibge, m.nome_municipio, m.uf, m.regiao, m.populacao_total;


--
-- Name: VIEW vw_municipio_indicadores; Type: COMMENT; Schema: sinisa; Owner: -
