--
-- Name: vw_resumo_regiao; Type: VIEW; Schema: sinisa; Owner: -
--

CREATE VIEW sinisa.vw_resumo_regiao AS
 SELECT regiao,
    count(*) AS municipios_respondentes,
    round((avg(irs3002_disposicao_inadequada))::numeric, 2) AS disposicao_inadequada_media,
    round((avg(irs0005_cobertura_coleta_seletiva))::numeric, 2) AS coleta_seletiva_media
   FROM sinisa.vw_municipio_indicadores
  WHERE (irs3002_disposicao_inadequada IS NOT NULL)
  GROUP BY regiao;


--
-- Name: VIEW vw_resumo_regiao; Type: COMMENT; Schema: sinisa; Owner: -
--

COMMENT ON VIEW sinisa.vw_resumo_regiao IS 'Disposição inadequada e coleta seletiva médias por região.';


--
-- Name: vw_resumo_uf; Type: VIEW; Schema: sinisa; Owner: -
--

CREATE VIEW sinisa.vw_resumo_uf AS
 SELECT uf,
    count(*) AS municipios_respondentes,
    round((avg(irs3002_disposicao_inadequada))::numeric, 2) AS media_simples,
    round(((sum((irs3002_disposicao_inadequada * (populacao_total)::double precision)) / (sum(populacao_total))::double precision))::numeric, 2) AS media_ponderada,
    round((percentile_cont((0.5)::double precision) WITHIN GROUP (ORDER BY irs3002_disposicao_inadequada))::numeric, 2) AS mediana
   FROM sinisa.vw_municipio_indicadores
  WHERE (irs3002_disposicao_inadequada IS NOT NULL)
  GROUP BY uf;


--
-- Name: VIEW vw_resumo_uf; Type: COMMENT; Schema: sinisa; Owner: -
--

COMMENT ON VIEW sinisa.vw_resumo_uf IS 'IRS3002 por UF: média simples, ponderada por população e mediana.';


